(7706706, 1265647, 114285, '<td valign="top">Another stunner Roz.</td>', 'Another stunner Roz.', '2021-11-15 08:58:51.000000', NULL, 1),
(7706710, 1265744, 38032, '<td valign="top">I love the image. Design-wise, it would have made more sense to go with less conventional use of the type - White type over dark parts of the image to make it more readbable.</td>', 'I love the image. Design-wise, it would have made more sense to go with less conventional use of the type - White type over dark parts of the image to make it more readbable.', '2021-11-15 09:25:39.000000', NULL, 1),
